(function () {
  const d = (function () { try { if (window.top && (window.top.document.querySelector('.mes') || window.top.document.querySelector('#chat'))) return window.top.document; } catch (e) {} return document; })();
  try { if (d.__pqOff) d.__pqOff(); } catch (e) {}
  ['pq-ball', 'pq-win', 'pq-style'].forEach(id => { const e = d.getElementById(id); if (e) e.remove(); });
  const M = d.documentElement || d.body;

  /* ========== 配置区 ========== */
  const BANNER_IMG = '';
  const WALLPAPER = '';
  const AVATARS = { '我': '' };
  const DEFAULT_CONTACTS = [];
  const DEFAULT_MSGS = {};
  const DEFAULT_POSTS = [];
  /* 头像: '名字': '图片链接' 或一个emoji，'我' 留空自动读酒馆用户头像
     联系人例: { name: '林深', lastMsg: '晚安', time: '23:10', unread: 1 }
     群聊例:   { name: '三人组', isGroup: true, members: ['甲', '乙', '我'], lastMsg: '', time: '昨天', unread: 0 }
     聊天例:   '林深': [{ sender: '林深', type: 'text', content: '到家了吗', time: '23:05', isMe: false }]
     动态例:   { author: '林深', content: '今晚的月亮', img: '月亮的照片', time: '1小时前', likes: ['甲'], comments: [{ name: '乙', text: '好看', to: '' }] } */

  const FONT = "'Noto Sans SC','PingFang SC','Microsoft YaHei','Helvetica Neue',Arial,sans-serif";
  let VW = 380, VH = 640;
  const readVP = () => { try { if (window.top && window.top.innerWidth) { VW = window.top.innerWidth; VH = window.top.innerHeight; } } catch (e) {} };
  readVP();
  let W = Math.min(380, VW - 16), H = Math.min(620, VH - 80);

  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const colorOf = n => { let h = 0; for (const c of String(n)) h = (h * 31 + c.charCodeAt(0)) % 360; return 'hsl(' + h + ',42%,55%)'; };
  const isUrl = v => /^(https?:\/\/|data:image\/|\/)/.test(String(v || ''));
  const clock = () => { const t = new Date(); return String(t.getHours()).padStart(2, '0') + ':' + String(t.getMinutes()).padStart(2, '0'); };
  const fmt = s => esc(s).replace(/(#[^#\s]+#)/g, '<span class="pq-at">$1</span>').replace(/(@[^\s@#]+)/g, '<span class="pq-at">$1</span>');
  const brief = m => m.type === 'img' ? '[图片]' : m.type === 'voice' ? '[语音]' : m.type === 'redpacket' ? '[红包]' : m.type === 'recall' ? '撤回了一条消息' : String(m.content || '').slice(0, 30);

  const offs = [];
  const on = (t, ev, fn, o) => { t.addEventListener(ev, fn, o); offs.push(() => t.removeEventListener(ev, fn, o)); };

  const CSS = `
#pq-win{all:initial;position:fixed;display:none;flex-direction:column;box-sizing:border-box;padding:8px;background:#0b0b0c;border-radius:44px;box-shadow:0 18px 60px rgba(0,0,0,.45),inset 0 0 0 1.5px #3a3a3c;transform-origin:90% 90%;z-index:2147483646;font-family:${FONT};color:#000;-webkit-text-size-adjust:100%}
#pq-win *{box-sizing:border-box;margin:0;padding:0;font-family:${FONT};letter-spacing:normal;text-shadow:none;-webkit-tap-highlight-color:transparent}
#pq-win .pq-scr{flex:1;min-height:0;display:flex;flex-direction:column;position:relative;overflow:hidden;background:#f5f5f5;border-radius:36px}
#pq-win .pq-notch{position:absolute;top:9px;left:50%;width:86px;height:24px;margin-left:-43px;background:#000;border-radius:12px;z-index:3;pointer-events:none}
#pq-win .pq-sb{flex:0 0 auto;height:44px;display:flex;align-items:center;justify-content:space-between;padding:6px 26px 0;font-size:14px;font-weight:600;color:#000;background:#f7f7f7;cursor:move;touch-action:none;user-select:none;-webkit-user-select:none}
#pq-win .pq-hd{flex:0 0 auto;height:44px;display:flex;align-items:center;justify-content:center;position:relative;background:#f7f7f7;border-bottom:.5px solid #d9d9d9;cursor:move;touch-action:none;user-select:none;-webkit-user-select:none}
#pq-win .pq-g{background:#ededed}
#pq-win .pq-ht{max-width:52%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:16px;font-weight:600;color:#000}
#pq-win .pq-hl{position:absolute;left:12px;display:flex;align-items:center;cursor:pointer;color:#576b95;font-size:14px;font-weight:500}
#pq-win .pq-hl b{font-size:24px;line-height:1;font-weight:400;margin-right:2px}
#pq-win .pq-hr{position:absolute;right:10px;display:flex;align-items:center;gap:2px}
#pq-win .pq-hb{cursor:pointer;padding:4px 7px;font-size:17px;line-height:1;color:#333}
#pq-win .pq-x{display:none!important}
#pq-win .pq-pbtn{padding:5px 14px;border-radius:6px;background:#1aad19;color:#fff;font-size:13px;font-weight:600;cursor:pointer}
#pq-win .pq-sc{flex:1;min-height:0;overflow-y:auto;overflow-x:hidden;background:#fff;-webkit-overflow-scrolling:touch;scrollbar-width:none}
#pq-win .pq-sc::-webkit-scrollbar,#pq-win .pq-body::-webkit-scrollbar{width:0;height:0}
#pq-win .pq-empty{padding:60px 20px;text-align:center;font-size:13px;color:#999}
#pq-win .pq-tb{flex:0 0 auto;height:58px;padding-bottom:8px;display:flex;background:rgba(247,247,247,.96);border-top:.5px solid #d9d9d9}
#pq-win .pq-tab{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;cursor:pointer}
#pq-win .pq-tw{position:relative;display:flex}
#pq-win .pq-ti{display:flex;color:#7d7d7d}
#pq-win .pq-tab.on .pq-ti{color:#07c160}
#pq-win .pq-tl{font-size:10px;font-weight:500;color:#999}
#pq-win .pq-tab.on .pq-tl{color:#07c160}
#pq-win .pq-badge{position:absolute;top:-4px;right:-4px;min-width:16px;height:16px;padding:0 4px;border-radius:8px;background:#f43530;color:#fff;font-size:10px;font-weight:600;line-height:16px;text-align:center}
#pq-win .pq-tw .pq-badge{right:-10px}
#pq-win .pq-it{position:relative;display:flex;align-items:center;gap:12px;padding:10px 14px;border-bottom:.5px solid #f2f2f2;background:#fff;cursor:pointer}
#pq-win .pq-it:active{background:#f5f5f5}
#pq-win .pq-aw{position:relative;flex:0 0 auto;display:flex}
#pq-win .pq-if{flex:1;min-width:0}
#pq-win .pq-nm{margin-bottom:2px;padding-right:44px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px;font-weight:500;color:#000}
#pq-win .pq-pv{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;color:#999}
#pq-win .pq-tm{position:absolute;top:11px;right:14px;font-size:11px;color:#bbb}
#pq-win .pq-ga{width:42px;height:42px;flex:0 0 42px;padding:3px;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:1px;background:#e0e0e0;border-radius:6px;overflow:hidden}
#pq-win .pq-gc{display:flex;align-items:center;justify-content:center;border-radius:2px;overflow:hidden;font-size:9px;color:#fff;background-size:cover;background-position:center}
#pq-win .pq-body{flex:1;min-height:0;overflow-y:auto;overflow-x:hidden;padding:12px 14px;background:#ededed;-webkit-overflow-scrolling:touch;scrollbar-width:none}
#pq-win .pq-ts{margin:10px 0;text-align:center;font-size:11px;color:#b5b5b5}
#pq-win .pq-sys{margin:8px 0;text-align:center;font-size:12px;color:#b5b5b5}
#pq-win .pq-row{display:flex;align-items:flex-start;gap:8px;margin:10px 0}
#pq-win .pq-row.me{flex-direction:row-reverse}
#pq-win .pq-col{display:flex;flex-direction:column;gap:3px;max-width:68%;min-width:0}
#pq-win .pq-row.me .pq-col{align-items:flex-end}
#pq-win .pq-sn{padding:0 4px;font-size:11px;color:#999}
#pq-win .pq-bub{padding:9px 12px;font-size:13px;line-height:1.6;color:#000;background:#fff;border-radius:4px 10px 10px 10px;text-align:left;word-break:break-word;white-space:pre-wrap}
#pq-win .pq-row.me .pq-bub{background:#95ec69;border-radius:10px 4px 10px 10px}
#pq-win .pq-vt{padding:0 4px;font-size:11px;line-height:1.5;color:#999;word-break:break-word}
#pq-win .pq-imgd{max-width:100%;padding:8px 10px;background:#fff;border-radius:6px;font-size:12px;line-height:1.5;font-style:italic;color:#888;word-break:break-word}
#pq-win .pq-img{display:block;max-width:160px;max-height:200px;border-radius:6px;object-fit:cover}
#pq-win .pq-rp{width:168px;overflow:hidden;background:#fff;border-radius:6px}
#pq-win .pq-rpt{padding:10px 12px;background:#fa9d3b;font-size:13px;line-height:1.4;color:#fff;word-break:break-word}
#pq-win .pq-rpf{padding:3px 12px;font-size:10px;color:#999}
#pq-win .pq-pd{display:flex;justify-content:flex-end;align-items:center;gap:5px;margin:6px 0;cursor:pointer}
#pq-win .pq-pdx{font-size:13px;line-height:1;color:#c9c9c9}
#pq-win .pq-pdb{max-width:68%;padding:9px 12px;background:rgba(149,236,105,.45);border-radius:10px 4px 10px 10px;font-size:13px;line-height:1.6;color:#4a6b38;word-break:break-word;white-space:pre-wrap}
#pq-win .pq-pdh{margin:2px 4px 0 0;text-align:right;font-size:10.5px;color:#b5b5b5}
#pq-win .pq-bar{flex:0 0 auto;height:66px;display:flex;align-items:center;gap:8px;padding:0 10px 14px;background:#f7f7f7;border-top:.5px solid #d9d9d9}
#pq-win .pq-ip{flex:1;min-width:0;height:34px;padding:0 12px;font-size:13px;color:#333;-webkit-text-fill-color:#333;background:#fff;border:.5px solid #e0e0e0;border-radius:6px;outline:none;box-shadow:none;caret-color:#1aad19;appearance:none;-webkit-appearance:none}
#pq-win .pq-sd{position:relative;flex:0 0 auto;width:56px;height:34px;border:none;border-radius:6px;background:#1aad19;color:#fff;font-size:13px;font-weight:600;cursor:pointer;transition:background .15s;appearance:none;-webkit-appearance:none}
#pq-win .pq-cnt{position:absolute;top:-6px;right:-6px;display:none;min-width:17px;height:17px;padding:0 4px;border-radius:9px;background:#fff;border:1.5px solid #1aad19;font-size:10px;font-weight:700;line-height:14px;text-align:center;color:#1aad19}
#pq-win .pq-cover{position:relative;height:140px;margin-bottom:28px;background:linear-gradient(135deg,#ff6b6b,#ee5a6f,#c44569);background-size:cover;background-position:center}
#pq-win .pq-cu{position:absolute;right:12px;bottom:-22px;display:flex;align-items:flex-end;gap:10px}
#pq-win .pq-cn{padding-bottom:26px;font-size:15px;font-weight:600;color:#fff;text-shadow:0 1px 3px rgba(0,0,0,.5)}
#pq-win .pq-cav{display:flex;border:2px solid #fff;border-radius:8px;background:#fff;overflow:hidden}
#pq-win .pq-po{display:flex;gap:10px;padding:12px 14px;border-bottom:.5px solid #f0f0f0;background:#fff}
#pq-win .pq-pb{flex:1;min-width:0}
#pq-win .pq-pn{margin-bottom:3px;font-size:14px;font-weight:600;color:#576b95}
#pq-win .pq-pt{font-size:13px;line-height:1.7;color:#333;white-space:pre-wrap;word-break:break-word}
#pq-win .pq-at{color:#576b95}
#pq-win .pq-pi{margin-top:6px;padding:8px 10px;background:#f7f7f7;border-radius:6px;font-size:12px;line-height:1.5;font-style:italic;color:#888;word-break:break-word}
#pq-win .pq-pimg{display:block;margin-top:6px;max-width:160px;max-height:200px;border-radius:4px;object-fit:cover}
#pq-win .pq-pf{display:flex;align-items:center;justify-content:space-between;margin-top:8px}
#pq-win .pq-ptm{font-size:11px;color:#999}
#pq-win .pq-ab{display:inline-block;margin-left:6px;padding:3px 8px;background:#f7f7f7;border-radius:12px;font-size:11px;color:#576b95;cursor:pointer}
#pq-win .pq-ab.on{color:#e54b65}
#pq-win .pq-ix{margin-top:8px;padding:6px 9px;background:#f5f5f5;border-radius:5px;font-size:12px;line-height:1.6;color:#333}
#pq-win .pq-lk{color:#576b95;word-break:break-word}
#pq-win .pq-lk+.pq-cm{margin-top:4px;padding-top:4px;border-top:.5px solid #e6e6e6}
#pq-win .pq-cm{word-break:break-word}
#pq-win .pq-cm b{font-weight:500;color:#576b95}
#pq-win .pq-cbody{flex:1;min-height:0;display:flex;flex-direction:column;gap:10px;padding:14px;background:#fff}
#pq-win .pq-ta{flex:1;min-height:120px;resize:none;border:none;outline:none;box-shadow:none;background:transparent;font-size:14px;line-height:1.7;color:#333;-webkit-text-fill-color:#333;caret-color:#1aad19;appearance:none;-webkit-appearance:none}
#pq-win .pq-bub{position:relative;border-radius:6px}
#pq-win .pq-row.me .pq-bub{border-radius:6px}
#pq-win .pq-bub::before{content:"";position:absolute;top:13px;left:-5px;border:5px solid transparent;border-left:0;border-right-color:#fff}
#pq-win .pq-row.me .pq-bub::before{left:auto;right:-5px;border:5px solid transparent;border-right:0;border-left-color:#95ec69}
#pq-win .pq-sc{padding-bottom:20px}
#pq-win .pq-hb svg{display:block}
#pq-win .pq-toast{position:absolute;left:50%;bottom:70px;transform:translateX(-50%);padding:8px 16px;border-radius:18px;background:rgba(0,0,0,.72);color:#fff;font-size:12px;z-index:5;pointer-events:none;white-space:nowrap}

#pq-win .pq-scr.pq-wp{background:linear-gradient(170deg,#1b2d3d 0%,#2c4e63 52%,#4f7f8f 100%);background-size:cover;background-position:center}
#pq-win .pq-scr.pq-wp:before{content:"";position:absolute;top:0;right:0;bottom:0;left:0;background:linear-gradient(rgba(8,16,24,.18),rgba(8,16,24,.38));pointer-events:none}
#pq-win .pq-wp .pq-sb,#pq-win .pq-wp .pq-home-page{position:relative;z-index:1}
#pq-win .pq-sbw{background:transparent;color:#fff}
#pq-win .pq-sbw svg{filter:invert(1)}

#pq-win .pq-home-page{background:transparent;padding:6px 0 26px;display:flex;flex-direction:column}
#pq-win .pq-wg{margin:10px 16px 0;padding:16px 18px;color:#fff;background:rgba(255,255,255,.16);border:.5px solid rgba(255,255,255,.28);border-radius:22px;-webkit-backdrop-filter:blur(18px);backdrop-filter:blur(18px)}
#pq-win .pq-wg-top{display:flex;justify-content:space-between;font-size:12px;opacity:.78}
#pq-win .pq-wg-city{margin-top:10px;font-size:30px;font-weight:600;line-height:1.1}
#pq-win .pq-wg-desc{margin-top:8px;font-size:12px;opacity:.82}
#pq-win .pq-wg-user{margin-top:14px;padding-top:12px;border-top:.5px solid rgba(255,255,255,.25);display:flex;align-items:center;gap:10px}
#pq-win .pq-wg-av{display:flex;border-radius:50%;overflow:hidden}
#pq-win .pq-wg-un{font-size:14px;font-weight:600}
#pq-win .pq-wg-us{margin-top:2px;font-size:11px;opacity:.7}
#pq-win .pq-app-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px 4px;padding:28px 14px 0}
#pq-win .pq-app{min-width:0;text-align:center;cursor:pointer}
#pq-win .pq-app:active .pq-app-icon{transform:scale(.92)}
#pq-win .pq-app-icon{width:58px;height:58px;margin:0 auto 6px;display:flex;align-items:center;justify-content:center;color:#fff;border-radius:14px;box-shadow:0 3px 8px rgba(0,0,0,.28);transition:transform .12s}
#pq-win .pq-app-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#fff;font-size:11px;text-shadow:0 1px 2px rgba(0,0,0,.45)}
#pq-win .pq-home-tip{margin:auto 22px 0;padding-top:24px;font-size:11px;line-height:1.7;color:rgba(255,255,255,.62);text-align:center}

#pq-win .pq-forum-page,#pq-win .pq-market-page{background:#f2f3f5}
#pq-win .pq-forum-tip{padding:9px 14px;font-size:11px;color:#8a8f96}
#pq-win .pq-fpost{display:flex;gap:10px;padding:13px 14px;background:#fff;border-bottom:.5px solid #ececec;cursor:pointer}
#pq-win .pq-fpost:active{background:#f7f7f7}
#pq-win .pq-fbody{flex:1;min-width:0}
#pq-win .pq-fhead{display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#8a8f96}
#pq-win .pq-fname{font-size:13px;font-weight:600;color:#4a5560}
#pq-win .pq-fmine{margin-left:4px;padding:0 5px;border-radius:3px;background:#e8f0ff;color:#4561e8;font-size:10px;font-weight:400}
#pq-win .pq-ftitle{margin-top:5px;font-size:15px;font-weight:600;line-height:1.4;color:#1f2933}
#pq-win .pq-ftext{margin-top:4px;font-size:13px;line-height:1.6;color:#5b6670;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;word-break:break-word}
#pq-win .pq-ffoot{margin-top:8px;font-size:11px;color:#a3abb2}
#pq-win .pq-fp-main{padding:14px;background:#fff}
#pq-win .pq-fp-au{display:flex;align-items:center;gap:10px}
#pq-win .pq-fp-title{margin-top:12px;font-size:17px;font-weight:700;line-height:1.45;color:#1f2933}
#pq-win .pq-fp-text{margin-top:8px;font-size:14px;line-height:1.8;color:#3a444d;white-space:pre-wrap;word-break:break-word}
#pq-win .pq-fp-sec{padding:12px 14px 8px;font-size:12px;color:#8a8f96}
#pq-win .pq-frep{display:flex;gap:10px;padding:12px 14px;background:#fff;border-bottom:.5px solid #f0f0f0}
#pq-win .pq-frep-t{margin-top:4px;font-size:13px;line-height:1.65;color:#333;white-space:pre-wrap;word-break:break-word}

#pq-win .pq-market-warning{margin:10px 12px 0;padding:9px 12px;color:#8a6d3b;background:#fff7e6;border-radius:8px;font-size:11px;line-height:1.6}
#pq-win .pq-mk{display:flex;gap:12px;margin:10px 12px 0;padding:12px;background:#fff;border-radius:12px}
#pq-win .pq-mk.sold{opacity:.5}
#pq-win .pq-mk-ic{flex:0 0 56px;height:56px;border-radius:12px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:22px;font-weight:600}
#pq-win .pq-mk-b{flex:1;min-width:0}
#pq-win .pq-mk-top{display:flex;align-items:center;gap:6px}
#pq-win .pq-mk-name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:15px;font-weight:600;color:#1f2933}
#pq-win .pq-mk-tag{flex:0 0 auto;padding:1px 6px;border-radius:4px;background:#fff1d6;color:#b7791f;font-size:10px}
#pq-win .pq-mk-sell{margin-top:3px;font-size:11px;color:#9aa3ab}
#pq-win .pq-mk-desc{margin-top:6px;font-size:12px;line-height:1.6;color:#5b6670}
#pq-win .pq-mk-eff{margin-top:4px;font-size:12px;line-height:1.6;color:#1b8a6b}
#pq-win .pq-mk-bot{margin-top:10px;display:flex;align-items:center;justify-content:space-between;gap:8px}
#pq-win .pq-mk-price{font-size:17px;font-weight:700;color:#f43530}
#pq-win .pq-mk-stock{margin-left:6px;font-size:11px;color:#9aa3ab}
#pq-win .pq-buy{padding:6px 14px;color:#fff;background:#f43530;border:0;border-radius:15px;font-size:12px;cursor:pointer}

#pq-win .pq-mask{position:absolute;top:0;right:0;bottom:0;left:0;z-index:4;display:flex;align-items:flex-end;background:rgba(0,0,0,.4)}
#pq-win .pq-sheet{width:100%;max-height:82%;display:flex;flex-direction:column;padding:14px 14px 30px;background:#fff;border-radius:18px 18px 0 0}
#pq-win .pq-sheet-h{display:flex;align-items:center;gap:8px}
#pq-win .pq-sheet-x{flex:0 0 auto;padding:2px 6px;font-size:22px;line-height:1;color:#999;cursor:pointer}
#pq-win .pq-mk-talk{flex:1;min-height:80px;max-height:180px;overflow-y:auto;margin-top:10px;padding:6px 8px;background:#f6f7f8;border-radius:10px;-webkit-overflow-scrolling:touch;scrollbar-width:none}
#pq-win .pq-mt{display:flex;margin:6px 0}
#pq-win .pq-mt.me{justify-content:flex-end}
#pq-win .pq-mt span{max-width:80%;padding:7px 10px;border-radius:8px;background:#fff;font-size:12px;line-height:1.55;color:#333;word-break:break-word;white-space:pre-wrap}
#pq-win .pq-mt.me span{background:#95ec69}
#pq-win .pq-chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
#pq-win .pq-chip{padding:4px 10px;border-radius:12px;background:#f2f3f5;color:#576b95;font-size:11px;cursor:pointer}
#pq-win .pq-mk-ask{display:flex;gap:8px;margin-top:10px}
#pq-win .pq-mk-buybtn{margin-top:12px;width:100%;height:40px;border:0;border-radius:20px;background:#f43530;color:#fff;font-size:14px;font-weight:600;cursor:pointer;appearance:none;-webkit-appearance:none}

#pq-win .pq-home{position:absolute;left:0;right:0;bottom:0;height:20px;z-index:3;cursor:pointer}
