`;
  const styleEl = d.createElement('style');
  styleEl.id = 'pq-style';
  styleEl.textContent = CSS;
  (d.head || M).appendChild(styleEl);

  /* ========== 数据 ========== */
  function getAll() {
    const out = [];
    try {
      const last = (typeof getLastMessageId === 'function') ? getLastMessageId() : 0;
      for (let i = 0; i <= last; i++) {
        try {
          const r = getChatMessages(i);
          const m = Array.isArray(r) ? r[0] : r;
          if (m) { if (m.message_id == null) m.message_id = i; out.push(m); }
        } catch (e) {}
      }
    } catch (e) {}
    return out;
  }
  function slash(cmd) {
    try {
      if (typeof triggerSlash === 'function') triggerSlash(cmd);
      else if (typeof TavernHelper !== 'undefined' && TavernHelper.triggerSlash) TavernHelper.triggerSlash(cmd);
    } catch (e) { alert('发送失败:' + e.message); }
  }
  const cleanName = s => {
    s = String(s || '').trim();
    if (!s || s.length > 20 || /[\n\r{}<>]/.test(s) || /function|=>|var |const |script/i.test(s)) return null;
    return s;
  };

  function parseDM(msgs) {
    const convos = {}, seq = {};
    let n = 0;
    const TYPES = ['text', 'voice', 'img', 'redpacket', 'system', 'recall'];
    let lastTime = '';
    for (const m of msgs) {
      const t = m.message || '';
      const wxRe = /<WX>([\s\S]*?)<\/WX>/g;
      let wxMatch;
      while ((wxMatch = wxRe.exec(t)) !== null) {
        const lines = wxMatch[1].trim().split('\n').map(l => l.trim()).filter(Boolean);
        let groupTarget = null, dmTarget = null;
        lines.forEach(line => {
          if (line.indexOf('[group]') === 0) groupTarget = cleanName(line.slice(7));
          else if (line.indexOf('[dm]') === 0) dmTarget = cleanName(line.slice(4));
        });
        const others = [];
        lines.forEach(line => {
          if (line[0] === '[') return;
          const p = line.split('|');
          if (p.length < 2) return;
          if (!TYPES.includes((p[1] || '').trim().toLowerCase())) return;
          const s = cleanName(p[0]);
          if (s && s !== '我' && others.indexOf(s) === -1) others.push(s);
        });
        const target = groupTarget || dmTarget || (others.length === 1 ? others[0] : null);
        if (!target) continue;
        const isGroupBlock = !!groupTarget;
        lines.forEach(line => {
          if (line.indexOf('[time]') === 0) { lastTime = line.slice(6).trim(); return; }
          if (line[0] === '[') return;
          const p = line.split('|');
          if (p.length < 2) return;
          const type = (p[1] || '').trim().toLowerCase();
          if (!TYPES.includes(type)) return;
          const sender = cleanName(p[0]);
          if (!sender) return;
          if (!isGroupBlock && sender !== '我' && sender !== target) return;
          const isMe = sender === '我';
          const content = p.slice(2).join('|').trim();
          if (!convos[target]) convos[target] = [];
          const arr = convos[target];
          if (isMe && arr.slice(-6).some(x => x.isMe && x.type === type && x.content === content)) return;
          arr.push({ sender, type, content, time: lastTime, isMe });
          seq[target] = ++n;
        });
      }
      if (m.role === 'user') {
        const match = t.match(/^【(?:微信|私信)】.*?回复(.+?)的消息[：:]([\s\S]*)$/);
        if (match) {
          const target = cleanName(match[1]), content = match[2].trim();
          if (target && content) {
            if (!convos[target]) convos[target] = [];
            const arr = convos[target];
            if (!arr.slice(-6).some(x => x.isMe && x.content === content)) {
              arr.push({ sender: '我', type: 'text', content, time: '', isMe: true });
              seq[target] = ++n;
            }
          }
        }
      }
    }
    return { convos, seq };
  }

  function parsePosts(msgs, u) {
    const dyn = [], idx = {};
    const defs = DEFAULT_POSTS.map(p => ({
      key: 'd\u0001' + p.author + '\u0001' + p.content, author: p.author, content: p.content || '', img: p.img || '', time: p.time || '',
      isMe: p.author === '我' || p.author === u, likeList: (p.likes || []).slice(),
      commentList: (p.comments || []).map(c => ({ name: c.name, text: c.text, to: c.to || '' })),
    }));
    const norm = s => (s === u ? '我' : s);
    const newest = author => {
      for (let i = dyn.length - 1; i >= 0; i--) if (dyn[i].author === author) return dyn[i];
      for (let i = 0; i < defs.length; i++) if (defs[i].author === author) return defs[i];
      return null;
    };
    const put = (author, content, img, time) => {
      const k = author + '\u0001' + content;
      let p = idx[k];
      if (!p) { p = { key: k, author, content, img: img || '', time: time || '', isMe: author === '我', likeList: [], commentList: [] }; idx[k] = p; dyn.push(p); }
      else { if (img && !p.img) p.img = img; if (time && !p.time) p.time = time; }
      return p;
    };
    const addLikes = (p, arr) => arr.forEach(n => { n = norm(n); if (n && p.likeList.indexOf(n) < 0) p.likeList.push(n); });
    const addCm = (p, name, text, to) => {
      name = norm(name || '');
      if (!name || !text) return;
      if (!p.commentList.some(c => c.name === name && c.text === text)) p.commentList.push({ name, text, to: to ? norm(to) : '' });
    };
    for (const m of msgs) {
      const t = m.message || '';
      if (m.role === 'user') {
        if (t.indexOf('【朋友圈】') !== 0) continue;
        let mt = t.match(/^【朋友圈】[^：:\n]*?发布动态[：:]([\s\S]*)$/);
        if (mt) {
          const im = mt[1].match(/^([\s\S]*?)(?:【图片[：:]([\s\S]*?)】)?\s*$/);
          put('我', (im[1] || '').trim(), (im[2] || '').trim(), '刚刚');
          continue;
        }
        mt = t.match(/^【朋友圈】[^：:\n]*?评论([^：:\n]+?)的动态[：:]([\s\S]*)$/);
        if (mt) {
          const p = newest(norm(mt[1].trim()));
          if (p) addCm(p, '我', mt[2].trim(), '');
        }
        continue;
      }
      if (m.role !== 'assistant') continue;
      const re = /<PYQ>([\s\S]*?)<\/PYQ>/g;
      let mm;
      while ((mm = re.exec(t)) !== null) {
        let cur;
        mm[1].split('\n').forEach(line => {
          line = line.trim();
          if (!line) return;
          const p = line.split(/[|｜]/).map(s => s.trim());
          if (p[0] === '发布') {
            const author = norm(p[1] || '');
            if (author && (p[2] || p[3])) cur = put(author, p[2] || '', p[3] || '', p[4] || '');
          } else if (p[0] === '帖') {
            cur = newest(norm(p[1] || ''));
          } else if (p[0] === '赞') {
            const target = cur === undefined ? newest('我') : cur;
            if (target) addLikes(target, p.slice(1));
          } else if (p[0] === '评论') {
            const target = cur === undefined ? newest('我') : cur;
            if (target) addCm(target, p[1], p[2], p[3]);
          }
        });
      }
    }
    return dyn.reverse().concat(defs);
  }

  function parseAttrs(s) {
    const out = {};
    const re = /([A-Za-z_][\w-]*)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
    let m;
    while ((m = re.exec(String(s || '')))) {
      out[m[1]] = m[2] !== undefined ? m[2] : m[3];
    }
    return out;
  }

  function parseMarket(msgs) {
    const map = {};
    const talk = {};
    const say = (id, from, text) => {
      if (!id || !text) return;
      (talk[id] = talk[id] || []).push({ from, text });
    };
    for (const m of msgs) {
      const text = String(m.message || '');
      if (m.role === 'user') {
        const mt = text.match(/^【黑市询价】商品id：([^；\n]+)；[\s\S]*?玩家询问：([\s\S]*?)(?:【要求】[\s\S]*)?$/);
        if (mt) say(mt[1].trim(), '我', mt[2].trim());
        continue;
      }
      if (m.role !== 'assistant') continue;

      const re = /<market\b([^>]*)\/?>/gi;
      let hit;
      while ((hit = re.exec(text))) {
        const a = parseAttrs(hit[1]);
        if (!a.id || !a.name) continue;
        map[a.id] = {
          id: a.id,
          seller: a.seller || '匿名卖家',
          name: a.name,
          type: a.type || '杂物',
          rank: a.rank || '凡品',
          price: Math.max(0, Number(a.price) || 0),
          stock: Math.max(0, Number(a.stock) || 1),
          eff: a.eff || '',
          desc: a.desc || ''
        };
      }

      const replyRe = /<market_reply\b((?:[^>"']|"[^"]*"|'[^']*')*?)\/?>/gi;
      while ((hit = replyRe.exec(text))) {
        const a = parseAttrs(hit[1]);
        say(a.id, a.seller || '卖家', a.text);
      }

      const resultRe = /<market_result\b([^>]*)\/?>/gi;
      while ((hit = resultRe.exec(text))) {
        const a = parseAttrs(hit[1]);
        if (a.id && a.ok === '0' && map[a.id]) {
          map[a.id].stock = 0;
          map[a.id].soldOut = true;
          map[a.id].result = a.reason || '商品已无法交易。';
        }
      }
    }
    return Object.values(map).filter(x => x.stock > 0 || x.soldOut).map(x => {
      x.talk = talk[x.id] || [];
      return x;
    });
  }

  function parseForum(msgs) {
    const posts = [];
    const findPost = (title, pid) => {
      if (pid) { const hit = posts.find(x => x.pid === pid); if (hit) return hit; }
      for (let i = posts.length - 1; i >= 0; i--) if (posts[i].title === title) return posts[i];
      return null;
    };
    const addPost = (author, title, content, time, mine, board, pid) => {
      if (!author || !title || !content) return;
      if (posts.some(x => x.title === title && x.author === author)) return;
      posts.push({ key: 'f' + posts.length, pid: pid || '', author, title, content, time: time || '', board: board || '', mine: !!mine, replies: [] });
    };
    const addReply = (author, title, content, time, mine, pid) => {
      const p = findPost(title, pid);
      if (!p || !author || !content) return;
      if (p.replies.some(r => r.author === author && r.content === content)) return;
      p.replies.push({ author, content, time: time || '', mine: !!mine });
    };
    for (const m of msgs) {
      const text = String(m.message || '');
      if (m.role === 'user') {
        let mt = text.match(/^【论坛发帖】(.+?)发布帖子《([^》]+)》[：:]([\s\S]*?)(?:【要求】[\s\S]*)?$/);
        if (mt) { addPost(mt[1].trim(), mt[2].trim(), mt[3].trim(), '刚刚', true, '', ''); continue; }
        mt = text.match(/^【论坛回帖】(.+?)回复《([^》]+)》[：:]([\s\S]*?)(?:【要求】[\s\S]*)?$/);
        if (mt) addReply(mt[1].trim(), mt[2].trim(), mt[3].trim(), '刚刚', true, '');
        continue;
      }
      if (m.role !== 'assistant') continue;

      const tagRe = /<(post|reply)\b((?:[^>"']|"[^"]*"|'[^']*')*?)\/?>/gi;
      let hit;
      while ((hit = tagRe.exec(text))) {
        const a = parseAttrs(hit[2]);
        if (hit[1].toLowerCase() === 'post') addPost(a.author, a.title, a.content, a.time, false, a.board, a.id);
        else addReply(a.author, a.title, a.content, a.time, false, a.post);
      }

      const re = /<FORUM>([\s\S]*?)<\/FORUM>/gi;
      let block;
      while ((block = re.exec(text))) {
        block[1].split('\n').forEach(line => {
          const p = line.trim().split(/[|｜]/).map(x => x.trim());
          if (p[0] === '帖' && p.length >= 4) addPost(p[1], p[2], p[3], p[4], false, '', '');
          else if (p[0] === '回' && p.length >= 4) addReply(p[1], p[2], p[3], p[4], false, '');
        });
      }
    }
    return posts.slice().reverse();
  }

  let cache = null;
  function snap() {
    if (cache) return cache;
    const msgs = getAll();
    let u = '我';
    for (const m of msgs) if (m.role === 'user' && m.name) u = m.name;
    const dm = parseDM(msgs);
    cache = {
      u,
      convos: dm.convos,
      seq: dm.seq,
      posts: parsePosts(msgs, u),
      market: parseMarket(msgs),
      forum: parseForum(msgs)
    };
    return cache;
  }

  /* ========== 状态 ========== */
  const readMark = {};
  const myLikes = new Set();
