  function getContacts() {
    const s = snap();
    const dynamic = s.convos;
    const contacts = [];
    const seen = {};
    const countIn = arr => arr.filter(m => !m.isMe && m.type !== 'system' && m.type !== 'recall').length;
    DEFAULT_CONTACTS.forEach(c => {
      const msgs = (DEFAULT_MSGS[c.name] || []).concat(dynamic[c.name] || []);
      const last = msgs[msgs.length - 1];
      const mark = readMark[c.name];
      const unread = (mark == null) ? (c.unread || 0) + countIn(dynamic[c.name] || []) : countIn(msgs.slice(mark));
      contacts.push({
        name: c.name, isGroup: c.isGroup || false, members: c.members || [],
        lastMsg: last ? (last.isMe ? '我: ' : (c.isGroup ? last.sender + ': ' : '')) + brief(last) : (c.lastMsg || ''),
        time: last ? (last.time || c.time || '') : (c.time || ''),
        unread, msgs, seq: s.seq[c.name] || 0,
      });
      seen[c.name] = true;
    });
    Object.keys(dynamic).forEach(name => {
      if (seen[name]) return;
      const msgs = dynamic[name];
      const last = msgs[msgs.length - 1];
      const senders = [];
      msgs.forEach(x => { if (!x.isMe && x.type !== 'system' && senders.indexOf(x.sender) === -1) senders.push(x.sender); });
      const isGroup = senders.length > 1;
      const mk = readMark[name];
      contacts.push({
        name, isGroup, members: isGroup ? senders.concat(['我']) : [],
        lastMsg: (last.isMe ? '我: ' : (isGroup ? last.sender + ': ' : '')) + brief(last),
        time: last.time || '', unread: countIn(mk == null ? msgs : msgs.slice(mk)), msgs, seq: s.seq[name] || 0,
      });
    });
    return contacts.sort((a, b) => b.seq - a.seq);
  }
  function totalUnread() {
    try { return getContacts().reduce((n, c) => n + (c.unread || 0), 0); } catch (e) { return 0; }
  }

  /* ========== 头像 ========== */
  let userAvCache = '';
  function userAv() {
