    market: svgIc('<path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><path d="M3 6h18"/><path d="M16 10a4 4 0 0 1-8 0"/>', 28),
    wechat: '<svg width="30" height="30" viewBox="0 0 24 24"><ellipse cx="9.2" cy="9.3" rx="7.4" ry="6.2" fill="#fff"/><ellipse cx="15.6" cy="14.6" rx="6.4" ry="5.2" fill="#fff" stroke="#2ebd4f" stroke-width="1.4"/><circle cx="6.7" cy="8.2" r="1" fill="#2ebd4f"/><circle cx="11.7" cy="8.2" r="1" fill="#2ebd4f"/></svg>'
