    const state = phoneState();
    const city = state.p && state.p.city ? state.p.city : '未知城市';
    const name = s.u || '我';
    const now = new Date();
    const dateStr = (now.getMonth() + 1) + '月' + now.getDate() + '日 星期' + '日一二三四五六'[now.getDay()];

    return sb().replace('class="pq-sb"', 'class="pq-sb pq-sbw"') +
      '<div class="pq-sc pq-home-page">' +
        '<div class="pq-wg">' +
